export const OFFICIAL_POSTAL_SOURCE_CATALOG_VERSION = 'official-postal-source-catalog-v2';

export type PostalSourceAuthority =
  | 'postal-operator'
  | 'government'
  | 'intergovernmental-postal-standard'
  | 'official-open-data'
  | 'official-derived-open-source'
  | 'open-source'
  | 'community'
  | 'commercial-or-restricted'
  | 'unknown';

export type PostalSourceTrustTier =
  | 'authoritative'
  | 'official'
  | 'official-derived'
  | 'open-reference'
  | 'community'
  | 'weak';

export type PostalSourceAvailability =
  | 'public-api'
  | 'auth-required-api'
  | 'bulk-open-data'
  | 'licensed-bulk-data'
  | 'commercial-or-restricted'
  | 'web-search'
  | 'no-normal-postcode'
  | 'unknown';

export type PostalSourceDepth =
  | 'postcode'
  | 'locality'
  | 'street'
  | 'address'
  | 'building'
  | 'delivery-point'
  | 'geo-only'
  | 'legal-framework';

export type PostalSourceValidationReadiness =
  | 'reference-eligible'
  | 'metadata-only';

export type PostalSourceRole =
  | 'postal-reference-data'
  | 'legal-framework-only';

export type OfficialPostalSourceProfile = {
  id: string;
  countryCodes: string[];
  label: string;
  authority: PostalSourceAuthority;
  trustTier: PostalSourceTrustTier;
  availability: PostalSourceAvailability;
  depth: PostalSourceDepth;
  sourceRole?: PostalSourceRole;
  validationReadiness?: PostalSourceValidationReadiness;
  url: string;
  sourceNames: string[];
  openSourceIds: string[];
  requiresCredential: boolean;
  notes: string[];
};

export type PostalSourceClassification = {
  tier: PostalSourceTrustTier;
  strength: 'strong' | 'weak';
  reason: string;
  matches: OfficialPostalSourceProfile[];
};

